<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Support\Facades\Storage; class Category extends Model { protected $guarded = []; public function subcategories() { return $this->hasMany(Subcategory::class); } public function products() { return $this->hasMany(Product::class); } public function getImageUrlAttribute() { if (!$this->image_path) return null; return str_starts_with($this->image_path, 'http') ? $this->image_path : Storage::url($this->image_path); } }